WARD_CODE_WIDTH = 5


def pad_ward_codes(apps, schema_editor):
    # Mã phường/xã chính thức có 5 chữ số; nguồn seed trả số trần nên mã "4"
    # (Phường Ba Đình) trùng mã tỉnh "4" (Cao Bằng) — update_or_create ghi đè
    # lẫn nhau và 5 phường trung tâm Hà Nội bị mất. Đệm 0 cho phường để tách hẳn.
    Location = apps.get_model('locations', 'Location')
    for ward in Location.objects.filter(level='ward').only('id', 'code'):
        padded = ward.code.zfill(WARD_CODE_WIDTH) if ward.code.isdigit() else ward.code
        if padded != ward.code:
            Location.objects.filter(pk=ward.pk).update(code=padded)


